sys_script_include.script:
var GHSS_Retry_Outbound = Class.create();
GHSS_Retry_Outbound.prototype = {
    initialize: function() {},
    checkEnvironment: function() {
        var interval = gs.getProperty("x_hsb11_mss_c_ghss.retry_interval_environment_check");
        var uri_prop = gs.getProperty("x_hsb11_mss_c_ghss.ghss_retry_uri");
        var responseStatusFilter = gs.getProperty("x_hsb11_mss_c_ghss.status_code");
        var gr = new GlideRecord("sys_outbound_http_log");
        gr.addQuery("response_status", "NOT IN", responseStatusFilter.split(','));
        gr.addEncodedQuery(interval);
        gr.addQuery("url", "STARTSWITH", uri_prop);
        gr.query();
        if (gr.hasNext()) {
            return false;
        } else {
            return true;
        }
    },

    retry: function() {
        var retry_cnt = gs.getProperty("x_hsb11_mss_c_ghss.ghss_retry_count");
        var gr = new GlideRecord("x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table");
        gr.addQuery("state", "error_ghss");
        gr.addQuery("response_code", "NOT IN", "200,400");
        gr.addQuery("retry_count", "<", retry_cnt);
        gr.query();
        while (gr.next()) {
            gr.state = "ready_ghss";
            gr.retry_count = gr.retry_count + 1;
            gr.update();
        }
    },

    type: 'GHSS_Retry_Outbound'
};
